class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Solution:
    def rotateRight(self, head, k):
        values = []
        cur = head
        while cur:
            values.append(cur.val)
            cur = cur.next
        if not values:
            return None

        k %= len(values)
        values = values[-k:] + values[:-k] if k else values
        dummy = ListNode()
        tail = dummy
        for value in values:
            tail.next = ListNode(value)
            tail = tail.next
        return dummy.next

