class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Solution:
    def rotateRight(self, head, k):
        if not head or not head.next:
            return head
        length = 0
        cur = head
        while cur:
            length += 1
            cur = cur.next
        k %= length

        for _ in range(k):
            prev, tail = None, head
            while tail.next:
                prev, tail = tail, tail.next
            prev.next = None
            tail.next = head
            head = tail
        return head

